  if(known&&!hasEffect(target,'silenced')){
    const initiate=target.choices?.magicInitiate as any;if(target.features.some(f=>unprefix(f)==='magic-initiate')&&initiate?.spells?.some((s:string)=>unprefix(s)==='shield')&&(target.resources.find(r=>r.id==='magic-initiate')?.current||0)>0)sources.push({id:'magic-initiate',resourceId:'magic-initiate'});
    if(!state.combat.active||target.choices?._slotTurn!==turnKey(state))for(const r of target.resources.filter(r=>/^(slot|pact)-[1-9]$/.test(r.id)&&r.current>0).sort((a,b)=>+a.id.at(-1)!-+b.id.at(-1)!))sources.push({id:r.id,resourceId:r.id});
  }
