function runAttackSequence(state:GameState,actor:Actor,steps:AttackStep[],dice:Dice,log:Log){for(let index=0;index<steps.length;index++){const step=steps[index],target=actorBy(state,step.targetId);if(target.dead){event(log,'projectile',step.action.name+': allocated target is already dead; remaining attack is not rerolled or reassigned',actor,undefined,[target.id]);continue;}const existing=new Set(state.choices.map(c=>c.id));attack(state,actor,target,step.action,step.rank,step.options,dice,log);const pending=state.choices.find(c=>!existing.has(c.id)&&c.kind==='shield-reaction');if(pending){pending.payload.continuation={actorId:actor.id,steps:steps.slice(index+1)};return;}}if(steps[0]?.action.source==='spell')onItemAction(actor,'spell');}
