function resumeMovement(state:GameState,continuation:MovementContinuation,dice:Dice,log:Log){const pending=state.choices.find(c=>c.kind.endsWith('-reaction')||c.kind.startsWith('mastery-'));if(pending)pending.payload.movementContinuation=structuredClone(continuation);else continueMovement(state,continuation,dice,log);}
