function exhaustion(a:Actor){return integer(Number(a.choices?.exhaustion||0),0,6,'Exhaustion');}
function turnKey(s:GameState){return `${s.combat.round}:${s.combat.turn}`;}
function ensureActive(a:Actor){assert(!a.draft,'DRAFT_ACTOR','Finish and activate the character before using game actions');assert(!a.dead,'DEAD_ACTOR','A dead creature cannot act');}
function budget(s:GameState,a:Actor){const b=s.combat.budgets[a.id];assert(b,'NOT_IN_COMBAT','Actor is not in initiative');return b;}
