const stateTurnActor=(s:GameState,a:Actor)=>s.combat.order[s.combat.turn]===a.id;
function featureContext(state:GameState,source:Actor,targets:Actor[],options:Record<string,any>,dice:Dice,log:Log):FeatureContext{return {state,source,targets,options,dice,log,addEffect,heal,spend,economy,attack,attackSequence:runAttackSequence,derive:deriveActor};}
