function deathSave(s:GameState,a:Actor,dice:Dice,log:Log){assert(a.hp.current===0&&!a.dead,'NO_DEATH_SAVE','Death saves require a living character at 0 HP');assert(a.deathSaves.successes<3,'STABLE','This creature is stable');if(s.combat.active){assert(s.combat.order[s.combat.turn]===a.id,'NOT_YOUR_TURN','Death save occurs on your turn');assert(a.choices?._deathSaveTurn!==turnKey(s),'ONCE_PER_TURN','Death save already made this turn');a.choices||={};a.choices._deathSaveTurn=turnKey(s);}const r=naturalD20(a,dice,log,'death save');if(r===20){a.hp.current=1;a.deathSaves={successes:0,failures:0};a.effects=a.effects.filter(e=>e.sourceId!=='zero-hp');}else if(r===1)a.deathSaves.failures=Math.min(3,a.deathSaves.failures+2);else if(r>=10)a.deathSaves.successes=Math.min(3,a.deathSaves.successes+1);else a.deathSaves.failures=Math.min(3,a.deathSaves.failures+1);if(a.deathSaves.failures>=3)a.dead=true;event(log,'death-save',`${a.name}: death save ${r}; ${a.deathSaves.successes} successes, ${a.deathSaves.failures} failures${r===20?' (regains 1 HP)':''}`,a,[{expression:'1d20',rolls:[r],total:r}]);}
export function createGameState(name:string):GameState{return {id:uid(),name:String(name||'Campaign').slice(0,100),rev:0,actors:[],scene:{width:30,height:20,gridFeet:5,walls:[],terrain:[],fog:false},combat:{active:false,round:0,turn:0,order:[],budgets:{}},choices:[],paused:false,events:[]};}
